 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("input[name='method']").val("comSprtSvcApplList");
    $("form[name='comSprtSvcFrm']").attr("action", "comSprtSvc.do");
    $("form[name='comSprtSvcFrm']").attr("method", "post");
    $("form[name='comSprtSvcFrm']").attr("onsubmit", "");
    { const nr = await scwin.tx_fnSearch(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil16601/jldfil16601.xml", { "method": "comSprtSvcApplList" }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.doubleSubmitCheck
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.doubleSubmitCheck = function () {
    /* sdd-asis-lifecycle:begin doubleSubmitCheck — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (scwin.doubleSubmitFlag) {
        return scwin.doubleSubmitFlag;
    } else {
        scwin.doubleSubmitFlag = true;
        return false;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnRegister
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnRegister = async function () {
    /* sdd-asis-lifecycle:begin fnRegister — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const bl = await scwin.fnApplComCntChk($c.util.getComponent('ipt_comSchdlId').getValue());
    if (bl === 'false') {
        await $c.win.alert('신청가능한 법인수를 초과하였습니다.\n다음에 신청해주세요.');
        return;
    }
    const consultHopTmVal = $("input[name='consultHopTmVal']");
    if (consultHopTmVal.val() === '' || consultHopTmVal == null) {
        await $c.win.alert("컨설팅 희망시기를 입력하세요.");
        consultHopTmVal.focus();
        return;
    }
    const chrgNm = $("input[name='chrgNm']");
    if (chrgNm == null || chrgNm == null) {
        await $c.win.alert("담당자 정보가 없습니다.");
        return;
    }
    for (var i = 0; i < chrgNm.length; i++) {
        const chrgNmEq = chrgNm.eq(i);
        if (chrgNm.eq(0).attr("value") == null || chrgNm.eq(0).attr("value") === "") {
            await $c.win.alert("담당자 1 성명을 입력하세요.");
            console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return;
        }
