                return;
            }
        }
    }
    const file = $("input[type='file']");
    let fCnt = 0;
    let fNmLength = 0;
    let fType = 0;
    let fSize = 0;
    for (var i = 0; i < file.length; i++) {
        if (file.eq(i).attr("value") !== '' && file.eq(i).attr("value") != null) {
            fCnt++;
            fNmLength += scwin.fnFileNmLengthChk(file.eq(i).attr("value"));
            fType += scwin.fnFileTypeChk(file.eq(i).attr("value"));
            fSize += $c.util.getComponent("attachUploadFile" + (i + 1)).files[0].size;
        }
